def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr, sec=sec,
                infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E)

def left_split(left, ps=0.33, lfi=0.35, eco=0.22, pcf=0.10):
    return [left * ps, left * lfi, left * eco, left * pcf]

def E_fr(ens, left, lr, rn, oth, ps=0.33, lfi=0.35, eco=0.22, pcf=0.10, reg=0.10):
    l = left_split(left, ps, lfi, eco, pcf)
    return [ens, l[0], lr, l[1], l[2], l[3], oth * (1 - reg), rn * 0.10, oth * reg, rn * 0.90]

